const $=s=>document.querySelector(s),safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let saved={};try{saved=JSON.parse(localStorage.getItem('wmp-v3')||'{}')}catch{}let level=Math.max(1,Math.min(50,saved.level||1)),rescued=saved.rescued||0,solo,network=null,state,selfId='solo',local={x:0,z:0},world,lastMission='',lastEvent=0,processedWins=new Set(),waypoint=null,path=[],walking=false,auto=false,timeOffset=0,lastUi=0,mapLast=0,previousPhase='',joined=false,connecting=false,lastFrame=performance.now(),lastPose=0,keys=new Set(),mapExpanded=false,portrait='',fps;const audio=new CitySound();
function save(){try{let p=solo?.players.solo;localStorage.setItem('wmp-v3',JSON.stringify({level:solo?.level||level,money:p?.balance??saved.money??250,inventory:p?.inventory||saved.inventory||[],rescued,seed:solo?.seed||saved.seed}))}catch{toast('Progres tidak dapat disimpan pada browser ini.')}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4800)}
let returnFocus;function modal(html){fps?.exit();returnFocus=document.activeElement;$('#modal-content').innerHTML=html.replace('<h2>','<h2 id="modal-title">');$('#modal').hidden=false;$('#close').focus();keys.clear()}function close(){mapExpanded=false;$('#modal').hidden=true;returnFocus?.focus()}$('#close').onclick=close;$('#modal').onclick=e=>{if(e.target===$('#modal'))close()};document.addEventListener('keydown',e=>{if(e.key==='Escape'){close();path=[];auto=false}if(e.key==='Tab'&&!$('#modal').hidden){let elements=[...$('#modal').querySelectorAll('button:not(:disabled),a[href],input')],first=elements[0],last=elements.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
function act(action){if(network){network.action(action)}else{let result=solo.act(selfId,action);if(!result.ok)toast(result.error);receive(solo.snapshot(),selfId);save()}if(action.type==='clue')audio.tone(660,.16);if(action.type==='claim'||action.type==='deliver')audio.tone(880,.22)}
function receive(s,id){if(!s?.players?.[id])return;state=s;selfId=id;timeOffset=s.now-Date.now();const p=state.players[id],key=s.m.seed+':'+s.m.level;let fresh=lastMission!==key;if(fresh){lastMission=key;level=s.m.level;lastEvent=0;previousPhase='';path=[];waypoint=null;auto=false;local={x:p.x,z:p.z};$('.world-wrap').classList.add('loading');try{world.build(s.m);portrait=world.portraitUrl;updatePortrait();world.focus(local.x,local.z,230,true)}catch(e){console.error(e);toast('Kota gagal dimuat. Muat ulang game untuk mencoba kembali.')}$('.world-wrap').classList.remove('loading');if(!network)save()}else if(!joined||distance(local,p)>12){local.x=p.x;local.z=p.z}joined=true;
for(let e of s.events)if(e.id>lastEvent){lastEvent=e.id;if(!fresh)toast(e.text);if(e.type==='found'||e.type==='rescued')audio.speak('Ketemu! Ayo kita pulang.');if(e.type==='captured')audio.speak('Wah, hewannya masuk truk!');if(e.type==='won')audio.speak('Hore! Sahabat kecil sudah pulang.')}
if(s.phase!==previousPhase){let prior=previousPhase;previousPhase=s.phase;if(s.phase==='won'&&!processedWins.has(key+':'+s.started)){processedWins.add(key+':'+s.started);if(!network){rescued++;save()}if(prior)resultDialog(true)}if(s.phase==='lost'&&prior)resultDialog(false)}
renderUI()}
function updatePortrait(){if(portrait){$('#pet-photo').src=portrait;$('#pet-photo').hidden=false;$('#pet-emoji').hidden=true}else{$('#pet-photo').hidden=true;$('#pet-emoji').hidden=false}}
function initSolo(newSeed=false){network?.leave();network=null;selfId='solo';lastMission='';joined=false;solo=new GameEngine(level,newSeed?Math.floor(Math.random()*1e8):saved.seed||Math.floor(Math.random()*1e8));solo.add('solo',saved.name||'Kamu');solo.players.solo.balance=saved.money??250;solo.players.solo.inventory=(saved.inventory||[]).filter(i=>ITEMS.some(x=>x.id===i));receive(solo.snapshot(),'solo');$('#player-count').textContent='SOLO · 1/8'}
try{world=new CityWorld($('#world'),inspect);new VisualAssets(world,()=>{world.portrait();portrait=world.portraitUrl;updatePortrait();$('#model-status').textContent='GLB siap';},toast);fps=new FirstPerson(world,{onInteract:inspect,onNotice:toast,isBlocked:()=>!$('#modal').hidden});initSolo()}catch(e){console.error(e);$('#world').innerHTML='<div class="webgl-error"><h2>WebGL belum tersedia</h2><p>Aktifkan akselerasi hardware browser, lalu muat ulang untuk memainkan kota 3D.</p></div>';throw e}
function me(){return state.players[selfId]}function clockNow(){return Date.now()+timeOffset}function left(){return Math.max(0,Math.ceil((state.deadline-clockNow())/1000))}function pet(){return animals[state.m.animal]}
function renderUI(){if(!state)return;let p=me(),m=state.m;$('#area').textContent=THEMES[m.theme];$('#level-label').textContent='Level '+String(m.level).padStart(2,'0');$('#lv').textContent=String(m.level).padStart(2,'0');$('#pet-name').textContent='Bantu temukan '+pet()[0]+'!';$('#pet-breed').textContent=pet()[1]+' • Kalung merah';$('#pet-emoji').textContent=pet()[2];$('#owner-name').textContent=m.owner;$('#reward').textContent=m.reward;$('#money').textContent=p.balance.toLocaleString('id-ID');$('#rescued').textContent=rescued;$('#xp').style.width=Math.min(100,8+rescued*4)+'%';$('#clue-count').textContent=p.clues+' / 3';let seen=p.lastSeen,at=seen?new Date(seen.at).toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit',second:'2-digit',timeZone:'Asia/Jakarta'}):'';let clues=[`Terakhir terlihat di ${THEMES[m.theme]}. Cari brosur atau tanya warga.`,`${pet()[1]}, memakai kalung merah. Potret di atas cocok dengan brosur ${m.owner}.`,seen?`Jejak pukul ${at} WIB: X ${Math.round(seen.x)}, Z ${Math.round(seen.z)}. Hewan dapat berpindah!`:'Dapatkan jejak terbaru melalui warga atau PetNet.'];$('#clue-list').innerHTML=clues.map((text,i)=>`<div class="clue ${i>=p.clues?'locked':''}"><span class="clue-icon">${i>=p.clues?'♧':['⌖','▧','🐾'][i]}</span><span>${i>=p.clues?'Petunjuk belum ditemukan':safe(text)}</span></div>`).join('');$('#timer-title').textContent=state.phase==='captured'?'Patroli kembali dalam':state.phase==='carrying'?'Antar sebelum patroli tiba':'Polisi satwa tiba dalam';let buttons={ready:'Mulai pencarian →',search:'Lihat jejak terakhir ⌕',carrying:state.carrier===selfId?'Arah ke rumah pemilik ⌂':'Lihat pembawa hewan →',captured:'Temukan truk polisi →',won:'Lihat hasil penyelamatan ♡',lost:'Coba lagi →'};$('#start').textContent=buttons[state.phase]||'Mulai';$('#player-count').textContent=(network?(network.isHost?'HOST':'ONLINE'):'SOLO')+' · '+Object.keys(state.players).length+'/8';$('#team-strip').innerHTML=Object.values(state.players).map(q=>`<div class="team-member"><span>${q.id===selfId?'● ':'○ '}${safe(q.name)}${q.id===state.carrier?' 🐾':''}</span><b>${q.mode==='team'?'Kolaborasi':'Kompetitor'} · ${q.balance} 🪙</b></div>`).join('');let seconds=state.phase==='ready'?m.duration:['won','lost'].includes(state.phase)?0:left();$('#timer').textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');$('#timer-bar').style.width=Math.min(100,seconds/(state.phase==='captured'?95:m.duration)*100)+'%';if($('#lobby-roster'))$('#lobby-roster').textContent=Object.values(state.players).map(q=>q.name).join(' · ');$('#coords').textContent=`X ${Math.round(local.x)} · Z ${Math.round(local.z)}`;let release=p.releaseAt>clockNow();$('#interact').textContent=release?'Membuka kandang… '+Math.ceil((p.releaseAt-clockNow())/1000)+' dtk':'E · Interaksi di sekitar';if(waypoint)$('#coords').textContent+=` · Tujuan ${Math.round(distance(local,waypoint))} u`}
$('#start').onclick=()=>{switch(state.phase){case'ready':act({type:'start'});world.focus(local.x,local.z,190,true);break;case'search':if(me().lastSeen){setWaypoint(me().lastSeen);toast('Ikuti penanda di peta. WASD untuk berjalan; arah tujuan ditampilkan di peta.');mapDialog()}else information();break;case'carrying':if(state.carrier===selfId){setWaypoint(state.m.ownerPos);inspect({type:'owner',name:state.m.owner,owner:state.m.owner,detail:'Pemilik menunggu di depan rumah.',...state.m.ownerPos})}else{let c=state.players[state.carrier];if(c)inspect({type:'player',name:c.name,...c})}break;case'captured':inspect({type:'truck',name:'Truk Polisi Satwa',...state.m.truck});break;case'won':resultDialog(true);break;case'lost':resultDialog(false)}};
function infoPhoto(){return portrait?`<img class="clue-photo" src="${portrait}" alt="Potret 3D ${safe(pet()[0])}">`:`<div class="big-emoji">${pet()[2]}</div>`}
function information(){modal(`<span class="eyebrow">PETNET • INTERNET DI DALAM GAME</span><h2>${safe(pet()[0])} belum pulang</h2>${infoPhoto()}<p><b>${safe(state.m.owner)}</b>: “${safe(pet()[0])} adalah ${safe(pet()[1])}. Ia memakai kalung merah dan terakhir terlihat di ${safe(THEMES[state.m.theme])}.”</p><p>PetNet adalah jejaring warga fiktif di dalam game. Jejak diperbarui dari posisi hewan saat laporan dibaca; waktu laporan dicatat karena hewan dapat bergerak.</p><button class="primary" id="read-clue">Simpan laporan terbaru →</button>`);$('#read-clue').onclick=()=>{act({type:'clue'});close();toast('Laporan disimpan. Baca lagi untuk memperbarui jejak.')}}$('#clue-btn').onclick=information;
function actionButtons(obj){let phase=state.phase,p=me();if(obj.type==='pet')return `<button class="primary" id="pickup" ${phase!=='search'?'disabled':''}>Jemput ${safe(pet()[0])} (≤15 u)</button>${p.inventory.includes('whistle')?'<button class="secondary" id="whistle">Gunakan peluit penenang</button>':''}`;if(obj.type==='owner')return phase==='carrying'&&state.carrier===selfId?'<button class="primary" id="deliver">Kembalikan hewan (≤22 u)</button>':'<button class="primary" id="ask">Tanya pemilik</button>';if(obj.type==='truck')return phase==='captured'?`<p class="status-banner">Tetap dekat truk selama membuka kandang. Patroli tetap berjalan ketika panel terbuka.</p><div class="object-actions"><button class="primary" id="hook">Pengait truk · 18 dtk</button>${p.inventory.includes('cutter')?'<button class="primary" id="cutter">Pemotong · 3 dtk</button>':''}${p.inventory.includes('torch')?'<button class="primary" id="torch">Las mini · 6 dtk</button>':''}</div>`:'<p>Truk patroli belum membawa hewan. Pengait gratis tersedia di kompartemen.</p>';if(['poster','tree','building','person','shop'].includes(obj.type))return '<button class="primary" id="ask">'+(obj.type==='person'?'Tanya warga':obj.type==='poster'||obj.type==='tree'?'Baca brosur':'Periksa brosur di pintu')+'</button>';if(obj.type==='player'&&obj.id!==selfId&&obj.id===state.carrier)return '<button class="primary danger" id="steal">Rebut hewan (≤15 u)</button>';return''}
function inspect(obj){if(!obj)return;let p=me();world.focus(obj.x,obj.z,Math.max(95,(obj.height||15)*3));let d=distance(local,obj);modal(`<span class="eyebrow">${obj.type==='pet'?'HEWAN PELIHARAAN':'JELAJAHI KOTA'}</span><h2>${safe(obj.name||'Objek kota')}</h2>${obj.type==='pet'||obj.type==='poster'?infoPhoto():''}<div class="info-meta"><span>Pemilik: ${safe(obj.owner||'Warga Maple')}</span><span>X ${Math.round(obj.x)} · Z ${Math.round(obj.z)}</span><span>${Math.round(d)} unit darimu</span></div><p>${safe(obj.detail||'Pemain dalam ruang yang sama.')}</p><div class="object-actions"><button class="secondary" id="walk-to">Tandai arah tujuan →</button><button class="secondary" id="mark">Tandai di City Map ⌖</button></div>${actionButtons(obj)}`);$('#walk-to').onclick=()=>{setWaypoint(obj);close();toast('Tujuan ditandai. Gerakkan karakter dengan WASD.')};$('#mark').onclick=()=>{setWaypoint(obj);close();toast('Tujuan ditandai di City Map.')};if($('#ask'))$('#ask').onclick=()=>{act({type:'clue'});audio.speak(`Saya melihat ${pet()[0]} di dekat taman. Coba ikuti jejaknya.`);close()};if($('#pickup'))$('#pickup').onclick=()=>{act({type:'claim'});close()};if($('#deliver'))$('#deliver').onclick=()=>{act({type:'deliver'});if(state.phase!=='won')close()};if($('#steal'))$('#steal').onclick=()=>{act({type:'steal'});close()};for(let id of ['hook','cutter','torch'])if($('#'+id))$('#'+id).onclick=()=>{act({type:'release',tool:id});close()};if($('#whistle'))$('#whistle').onclick=()=>{act({type:'whistle'});close()}}
function interact(){if(!$('#modal').hidden)return;let objects=[{type:'owner',name:state.m.owner,...state.m.ownerPos},{type:'truck',name:'Truk Polisi Satwa',...state.m.truck}];if(state.phase==='search')objects.push({...world.petInfo,...state.pet});if(state.phase==='carrying'&&state.carrier!==selfId){let c=state.players[state.carrier];if(c)objects.push({type:'player',...c})}objects.push(...world.posters,...world.npcs.map(n=>({type:'person',name:n.fisher?'Pak Damar, pemancing':'Warga Maple',owner:'Warga Maple',detail:'Tanya warga untuk jejak terbaru.',x:n.x,z:n.z})));objects.sort((a,b)=>distance(local,a)-distance(local,b));if(distance(local,objects[0])<28)inspect(objects[0]);else toast('Tidak ada objek interaksi dalam 28 unit. Klik objek untuk menandai tujuannya.')}$('#interact').onclick=interact;
function setWaypoint(pos){waypoint={x:pos.x,z:pos.z};path=[];auto=false}
const districtColors={office:'#b5b6aa',homes:'#cdbb9b',shops:'#cba77d',park:'#86a267',market:'#d4ab6f',farm:'#ac9f67'};
function drawMap(canvas,large=false){if(!state)return;let ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height,scale=w/1000,point=(x,z)=>[(x+500)*scale,(z+500)*scale];ctx.clearRect(0,0,w,h);ctx.fillStyle='#d5dbbb';ctx.fillRect(0,0,w,h);for(let b of world.plan.blocks){ctx.fillStyle=districtColors[b.kind];let [x,z]=point(b.x-39,b.z-39);ctx.fillRect(x,z,78*scale,78*scale)}ctx.strokeStyle='#eae6ca';ctx.lineWidth=16*scale;for(let q=-450;q<=450;q+=100){let [x,z]=point(q,q);ctx.beginPath();ctx.moveTo(0,z);ctx.lineTo(w,z);ctx.moveTo(x,0);ctx.lineTo(x,h);ctx.stroke()}ctx.fillStyle='#69a3a1';ctx.fillRect((world.plan.river+500-36)*scale,0,72*scale,h);ctx.fillStyle='#c9c1a1';for(let z of [-450,-150,150,450])ctx.fillRect((world.plan.river+500-40)*scale,(z+500-10)*scale,80*scale,20*scale);let dot=(pos,color,r=3,label)=>{let[x,y]=point(pos.x,pos.z);ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fillStyle=color;ctx.fill();ctx.lineWidth=1.5;ctx.strokeStyle='#fff9e5';ctx.stroke();if(label&&large){ctx.font='bold 12px sans-serif';ctx.fillStyle='#294e3c';ctx.fillText(label,x+8,y-7)}};dot(state.m.ownerPos,'#567642',large?6:3,'Rumah '+state.m.owner);dot(state.m.truck,'#797d9c',large?6:3,'Truk');if(me().lastSeen&&me().clues>=3){dot(me().lastSeen,'#bc9f54',large?5:3,'Jejak terakhir')}if(me().inventory.includes('digital')&&state.phase==='search')dot(state.pet,'#d28943',large?7:4,'🐾 '+pet()[0]);if(waypoint){let[x,y]=point(waypoint.x,waypoint.z);ctx.strokeStyle='#b66d3d';ctx.lineWidth=2;ctx.beginPath();ctx.arc(x,y,large?10:5,0,Math.PI*2);ctx.stroke()}for(let p of Object.values(state.players)){let pos=p.id===selfId?local:p;dot(pos,p.id===selfId?'#d17d39':p.mode==='team'?'#5f8cb1':'#bd6d69',large?6:4,p.id===selfId?'Kamu':p.name)}if(large){ctx.fillStyle='#567149';ctx.font='10px sans-serif';ctx.fillText('−500, −500',6,14);ctx.fillText('+500, +500',w-80,h-7)}}
function mapClick(canvas,e){let r=canvas.getBoundingClientRect();let pos={x:(e.clientX-r.left)/r.width*1000-500,z:(e.clientY-r.top)/r.height*1000-500};setWaypoint(pos);world.focus(pos.x,pos.z,230);toast('Tujuan ditandai: X '+Math.round(pos.x)+', Z '+Math.round(pos.z)+'.');if(mapExpanded)$('#map-destination').textContent=`Tujuan: X ${Math.round(pos.x)}, Z ${Math.round(pos.z)}`}$('#minimap').onclick=e=>mapClick($('#minimap'),e);function mapDialog(){modal(`<span class="eyebrow">CITY MAP • ${safe(THEMES[state.m.theme])}</span><h2>Kota 1.000 × 1.000 unit</h2><p class="map-instruction">Klik peta untuk menandai tujuan. Pemain tetap berjalan dari sudut pandang orang pertama. Titik hewan hanya ditampilkan dengan digital map; jejak lama ditampilkan setelah tiga petunjuk.</p><canvas class="map-large" id="large-map" width="650" height="650" role="img" aria-label="Peta lengkap kota interaktif"></canvas><div class="map-key"><span>▧ Perkantoran</span><span>▧ Perumahan</span><span>▧ Pertokoan</span><span>🌳 Taman</span><span>🌊 Sungai</span><span>🟠 Kamu</span><span>🟢 Pemilik</span><span>🔵 Tim</span><span>🔴 Kompetitor</span></div><p id="map-destination" class="direction">${waypoint?`Tujuan: X ${Math.round(waypoint.x)}, Z ${Math.round(waypoint.z)}`:'Pilih lokasi pada peta.'}</p><button class="primary" id="auto-walk">Gunakan tujuan ini →</button>`);mapExpanded=true;drawMap($('#large-map'),true);$('#large-map').onclick=e=>mapClick($('#large-map'),e);$('#auto-walk').onclick=()=>{if(!waypoint){toast('Pilih titik tujuan terlebih dahulu.');return}close();toast('Tujuan ditandai. WASD untuk berjalan, mouse untuk melihat sekeliling.')}}$('#map').onclick=$('#map-expand').onclick=mapDialog;
function shop(){modal(`<span class="eyebrow">TOKO PERALATAN</span><h2>Bekal untuk sahabat kecil</h2><p>Saldo: 🪙 ${me().balance} koin. Peralatan aktif setelah dibeli.${network?' Saldo multiplayer terpisah dari mode solo.':''}</p><div class="shop-grid">${ITEMS.map(i=>`<div class="item"><span>${i.icon}</span><strong>${i.name}</strong><p>${i.description}</p><button data-buy="${i.id}" ${me().inventory.includes(i.id)||me().balance<i.price?'disabled':''}>${me().inventory.includes(i.id)?'✓ Aktif':i.price+' koin · Beli'}</button></div>`).join('')}</div>`);document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{act({type:'buy',item:b.dataset.buy});if(network){b.disabled=true;b.textContent='Menunggu host…';setTimeout(()=>{if(!$('#modal').hidden)shop()},450)}else shop()})}
function changeLevel(n){if(network){if(!network.isHost){toast('Hanya host yang dapat mengganti level.');return}network.reset(n)}else{solo.reset(n,Date.now());receive(solo.snapshot(),'solo');save()}}
function levels(){modal(`<span class="eyebrow">50 LEVEL • 6 LINGKUNGAN</span><h2>Petualangan yang terus berubah</h2><p>Semua level seluas 1.000 × 1.000 unit. Susunan distrik, jenis hewan acak, pemilik, rute hewan, reward dan batas waktu berubah di setiap level.${network?' Hanya host yang dapat mengganti level bersama.':''}</p><div class="level-grid">${Array.from({length:50},(_,i)=>`<button data-level="${i+1}" class="${level===i+1?'current':''}" ${network&&!network.isHost?'disabled':''} title="${THEMES[i%6]}">${String(i+1).padStart(2,'0')}</button>`).join('')}</div>`);document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{close();changeLevel(+b.dataset.level)})}
function resultDialog(won){let m=state.m,payout=state.payout?.[selfId]||0;modal(`<div class="big-emoji">${won?pet()[2]+' 🏡':'🚚'}</div><span class="eyebrow">${won?'MISI BERHASIL':'MISI BELUM BERHASIL'}</span><h2>${won?safe(pet()[0])+' sudah pulang!':'Patroli menangkap pembawa hewan'}</h2><p>${won?`${safe(m.owner)} berterima kasih. Hadiah total ${m.reward} koin. ${network?'Pemain kolaborasi berbagi hadiah; pengantar kompetitif menerima seluruh hadiah.':''}`:'Waktu habis sebelum hewan dikembalikan. Pelajari petunjuk dan coba lagi.'}</p>${won?`<div class="info-meta"><span>Bagian kamu: 🪙 ${payout} koin</span></div>`:''}<button class="primary" id="continue" ${network&&!network.isHost?'disabled':''}>${network&&!network.isHost?'Menunggu host':won?(m.level===50?'Mainkan petualangan baru':'Lanjut ke level '+(m.level+1)):'Ulangi level ini'}</button>`);$('#continue').onclick=()=>{close();changeLevel(won?(m.level%50)+1:m.level)}}
function lobby(){if(network){modal(`<span class="eyebrow">MULTIPLAYER • WEBRTC</span><h2>${network.isHost?'Ruang kamu siap':'Kamu berada di ruang'}</h2><p>Bagikan seluruh kode berikut kepada pemain yang sudah memiliki akses ke situs ini. Host harus tetap membuka game.</p><div class="room-code" id="room-code"></div><button class="secondary" id="copy-code">Salin kode ruang</button><p class="connection">${Object.keys(state.players).length}/8 pemain terhubung. ${network.isHost?'Kamu host dan mengendalikan pergantian level.':'Waktu, hewan, dan hadiah disinkronkan dari host.'}</p><div id="lobby-roster"></div><button class="primary" id="toggle-mode">Pilih ${me().mode==='team'?'kompetisi':'kolaborasi'}</button><p>Kolaborasi: hadiah dibagi kepada anggota tim. Kompetisi: pengantar mendapat seluruh hadiah. Tekan E di dekat pembawa hewan untuk merebutnya; jarak maksimal 15 unit, cooldown 12 detik.</p><button class="secondary" id="leave-room">Keluar dan kembali ke mode solo</button>`);$('#room-code').textContent=network.code;$('#lobby-roster').textContent=Object.values(state.players).map(p=>p.name).join(' · ');$('#copy-code').onclick=async()=>{try{await navigator.clipboard.writeText(network.code);$('#copy-code').textContent='✓ Kode tersalin'}catch{$('#copy-code').textContent='Pilih dan salin kode di atas secara manual.'}};$('#toggle-mode').onclick=()=>{act({type:'mode'});close()};$('#leave-room').onclick=()=>{close();saved=readSaved();initSolo();toast('Kembali ke mode solo. Progres solo dipulihkan.')} ;return}modal(`<span class="eyebrow">MULTIPLAYER • MAKSIMUM 8 PEMAIN</span><h2>Teman satu tim. Atau pesaing?</h2><p>Buat ruang atau masukkan kode dari host. Semua pemain mendapat lokasi awal acak dan saldo awal 250 koin. Progres solo tetap terpisah.</p><div class="lobby-fields"><label for="player-name">Nama penjelajah</label><input id="player-name" maxlength="22" placeholder="Nama kamu" autocomplete="nickname"><label for="join-code">Kode ruang dari host</label><input id="join-code" maxlength="100" placeholder="ABCDEF~kode-host"><div class="lobby-actions"><button class="primary" id="host-room">Buat ruang baru</button><button class="primary" id="join-room">Gabung ke ruang</button></div></div><p class="connection" id="net-info">Menggunakan WebRTC dan relay MQTT publik untuk menemukan pemain. Koneksi antarperangkat bergantung pada jaringan; tidak ada relay TURN khusus. Host mengatur state permainan dan harus tetap online.</p><p>Privasi akses situs tetap mengikuti pengaturan situs ini. Membagikan kode ruang tidak memberikan akses situs kepada orang baru.</p>`);$('#player-name').value=saved.name||'';$('#host-room').onclick=()=>connect(true);$('#join-room').onclick=()=>connect(false)}
function readSaved(){try{return JSON.parse(localStorage.getItem('wmp-v3')||'{}')}catch{return{}}}
async function connect(host){if(connecting)return;let name=$('#player-name').value.trim()||'Penjelajah',code=$('#join-code').value.trim();if(!host&&!code){$('#net-info').textContent='Masukkan kode ruang dari host.';return}connecting=true;$('#host-room').disabled=$('#join-room').disabled=true;$('#net-info').textContent='Menghubungkan ke jaringan multiplayer…';let net=new Multiplayer({onState:(s,id)=>{if(network===net)receive(s,id)},onMessage:toast,onDisconnect:message=>{toast(message);network=null;joined=false;saved=readSaved();initSolo()}});try{save();saved=readSaved();saved.name=name;localStorage.setItem('wmp-v3',JSON.stringify(saved));network=net;joined=false;lastMission='';await net.connect({host,code,name,level});if(host){lobby();toast('Ruang dibuat. Bagikan kode kepada maksimal tujuh teman.')}else{close();toast('Mencari host… game solo dijeda sampai tersambung.');modal(`<span class="eyebrow">MENGHUBUNGKAN MULTIPLAYER</span><h2>Mencari host…</h2><p>Pastikan kode sama persis dan host membuka game. Koneksi dapat memerlukan beberapa detik. Jika jaringan memblokir WebRTC, coba jaringan lain.</p><button class="primary" id="cancel-join">Batalkan dan kembali solo</button>`);$('#cancel-join').onclick=()=>{close();net.leave();network=null;saved=readSaved();initSolo()};let check=setInterval(()=>{if(network!==net){clearInterval(check);return}if(joined){clearInterval(check);close();toast('Terhubung! Kamu masuk di lokasi acak.')}},300)}}catch(e){net.leave();network=null;joined=false;saved=readSaved();initSolo();lobby();$('#net-info').textContent=e.message||'Koneksi gagal. Coba lagi.'}finally{connecting=false}}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>({play:()=>close(),levels,shop,models:()=>window.open('./models.html','_blank','noopener'),multi:lobby}[b.dataset.tab])());
$('#help').onclick=()=>modal(`<span class="eyebrow">PANDUAN PENJELAJAH</span><h2>Where’s My Pet?</h2><p><b>Dunia:</b> 1.000 × 1.000 unit Three.js, X dan Z dari −500 hingga 500. Siang dan malam mengikuti waktu riil Jakarta (WIB).</p><p><b>Kontrol:</b> WASD / tombol panah berjalan, Shift berlari. Tombol arah di layar untuk perangkat sentuh. Klik Masuk ke kota untuk mengunci mouse. Mouse melihat sekeliling, Esc membebaskan mouse. Scroll / +− untuk zoom optik. ⌖ mengembalikan pandangan lurus. Tekan E untuk interaksi dalam 28 unit. City Map dapat diklik; ikuti penanda dengan menggerakkan karakter sendiri.</p><p><b>Misi:</b> mulai pencarian, baca brosur di pohon/rumah/tiang atau tanya warga dan PetNet. Kumpulkan tiga petunjuk. Hewan berhenti lalu berpindah setiap ${state.m.moveEvery} detik; waktu laporan penting. Dekati hewan (≤15 unit), jemput, lalu antar ke pemilik (≤22 unit).</p><p><b>Polisi satwa:</b> jika pencarian habis, hewan diamankan. Dekati truk (≤22 unit), buka kandang dengan pengait gratis (18 detik), pemotong (3 detik), atau las (6 detik). Jangan menjauh selama membuka kandang. Setelah bebas, kamu punya 120 detik mengantar sebelum patroli menangkapmu.</p><p><b>Multiplayer:</b> maksimal 8 pemain. Host menyinkronkan misi; petunjuk dan reward dibagi anggota kolaborasi. Kompetitor bisa merebut hewan di dekat pemain pembawa. Host tetap membuka game. Saldo multiplayer dimulai dari 250 koin per sesi, terpisah dari solo.</p><p><b>Audio:</b> klik ♫ untuk mengaktifkan aset suara ElevenLabs yang sudah tersedia. Status sumber audio ditampilkan pada HUD. PetNet adalah internet fiktif di dalam game; potret hewan adalah render model 3D.</p>`);
$('#sound').onclick=async()=>{try{let enabled=await audio.toggle();$('#sound').textContent=enabled?'♪':'♫';$('#sound').setAttribute('aria-label',enabled?'Matikan suara':'Aktifkan suara');toast(enabled?'Audio lingkungan ElevenLabs aktif.':'Suara dimatikan.')}catch(e){toast(e.message||'Audio belum tersedia.');$('#audio-status').textContent='ElevenLabs belum terhubung'}};$('#zoomin').onclick=()=>fps.zoom=true;$('#zoomout').onclick=()=>fps.zoom=false;$('#resetcam').onclick=()=>{fps.pitch=0;fps.zoom=false};$('#fps-play').onclick=()=>{if(state.phase==='ready')act({type:'start'});fps.enter()};$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('.world-wrap').requestFullscreen()}catch{toast('Layar penuh tidak tersedia pada browser ini.')}};
function tickClock(){let d=new Date();$('#clock').textContent=d.toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Jakarta'})+' WIB';$('#period').textContent=world.updateDay();$('.weather').firstChild.textContent=world.day==='Malam'?'☾ ':'☀ '}tickClock();setInterval(tickClock,10000);
const moveKeys=['w','a','s','d','W','A','S','D','ArrowUp','ArrowLeft','ArrowDown','ArrowRight','Shift'];document.addEventListener('keydown',e=>{if(!$('#modal').hidden)return;if(moveKeys.includes(e.key)){e.preventDefault();keys.add(e.key.toLowerCase());if(e.key!=='Shift'){auto=false;path=[]}}if(e.key.toLowerCase()==='e'){e.preventDefault();if(fps.aim)fps.pick();else interact()}});document.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>keys.clear());let controls=document.createElement('div');controls.className='mobile-controls';controls.innerHTML='<button aria-label="Berjalan ke kiri">←</button><button aria-label="Berjalan maju">↑</button><button aria-label="Berjalan mundur">↓</button><button aria-label="Berjalan ke kanan">→</button>';$('.world-wrap').appendChild(controls);[...controls.children].forEach((b,i)=>{let key=['a','w','s','d'][i];b.onpointerdown=e=>{e.preventDefault();auto=false;path=[];keys.add(key);b.setPointerCapture(e.pointerId)};b.onpointerup=b.onpointercancel=()=>keys.delete(key)});
setInterval(()=>{if(!network&&solo){solo.tick();receive(solo.snapshot(),'solo')}},100);
function frame(t){requestAnimationFrame(frame);let dt=Math.min((t-lastFrame)/1000,.05);lastFrame=t;if(!state)return;walking=false;let canMove=(!network||joined)&&$('#modal').hidden&&(fps.locked||fps.touch);let p=me();if(canMove){let forward=(keys.has('w')||keys.has('arrowup')?1:0)-(keys.has('s')||keys.has('arrowdown')?1:0),right=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),v=movementVector(fps.yaw,forward,right);if(forward||right){walking=true;let speed=6.5*Math.max(1,...ITEMS.filter(i=>p.inventory.includes(i.id)).map(i=>i.speed||1))*(keys.has('shift')?1.45:1),step=speed*dt,dx=v.x*step,dz=v.z*step,jet=p.inventory.includes('jet');if(world.canWalk(local.x+dx,local.z,jet))local.x+=dx;if(world.canWalk(local.x,local.z+dz,jet))local.z+=dz}}if(t-lastPose>100&&canMove){lastPose=t;if(network)network.pose(local);else solo.pose(selfId,local,Date.now())}world.walking=walking;world.update(dt,t/1000,state,selfId,local);audio.update(t/1000,walking,{world,state,selfId,local,yaw:fps.yaw});if(t-lastUi>250){lastUi=t;renderUI()}if(t-mapLast>180){mapLast=t;drawMap($('#minimap'));if(mapExpanded&&$('#large-map'))drawMap($('#large-map'),true)}}requestAnimationFrame(frame);setTimeout(()=>toast('Mode FPS siap. Klik Masuk ke kota, WASD bergerak, mouse melihat sekeliling.'),700);
